def attach_particle(word: str, particle: str) -> str:
    """Attach the correct form of a Korean particle to a word."""

    last_char = word[-1]
    has_batchim = False
    has_rieul = False

    # Check if last character is a Hangul syllable
    if ord('가') <= ord(last_char) <= ord('힣'):
        # Hangul syllable - calculate if it has a batchim
        code = ord(last_char) - ord('가')
        final_index = code % 28
        has_batchim = final_index != 0
        has_rieul = final_index == 8  # ㄹ is the 8th final consonant
    else:
        # Digit - extract all trailing digits and determine pronunciation
        digit_str = ""
        i = len(word) - 1
        while i >= 0 and word[i].isdigit():
            digit_str = word[i] + digit_str
            i -= 1

        has_batchim, has_rieul = _number_has_batchim(digit_str)

    # Special case for "으로/로" with ㄹ batchim
    if particle == "으로/로":
        if has_rieul:
            return word + "로"
        elif has_batchim:
            return word + "으로"
        else:
            return word + "로"

    # Select appropriate particle form
    forms = particle.split('/')
    if has_batchim:
        return word + forms[0]
    else:
        return word + forms[1]


def _number_has_batchim(digit_str: str) -> tuple:
    """Determine if a digit string ends with a batchim when read as Sino-Korean.

    Returns: (has_batchim, has_rieul_batchim)
    """

    # Map single digits to their batchim status
    # When read alone as Sino-Korean
    digit_batchim = {
        '0': (False, False),  # 영/공 - no batchim
        '1': (True, True),    # 일 - ㄹ batchim
        '2': (False, False),  # 이 - no batchim
        '3': (True, False),   # 삼 - ㅁ batchim
        '4': (False, False),  # 사 - no batchim
        '5': (False, False),  # 오 - no batchim
        '6': (True, False),   # 육 - ㄱ batchim
        '7': (True, True),    # 칠 - ㄹ batchim
        '8': (True, True),    # 팔 - ㄹ batchim
        '9': (True, False),   # 구 - ㄱ batchim
    }

    # Determine the pronunciation based on place value
    # For numbers: we read from left to right with place values
    # The key is what the number ends with phonetically

    length = len(digit_str)

    if length == 1:
        return digit_batchim[digit_str[0]]

    # For multi-digit numbers, check the last non-zero digit and place value
    # For example: 10 = "십" (ㅂ), 15 = "십오" (no batchim), 20 = "이십" (ㅂ)

    # Find the actual last pronounced element
    last_digit = digit_str[-1]

    if last_digit == '0':
        # Ends in 0 - we say the previous digit + place value word
        # 10, 20, 30... = "십", "이십", "삼십" etc. - all end with ㅂ batchim from 십
        if length == 2:
            # 10-90: all end in "십" which has ㅂ batchim
            return (True, False)
        elif length == 3:
            # 100-900: all end in "백" which has ㄱ batchim
            return (True, False)
        elif length == 4:
            # 1000-9000: all end in "천" which has ㄴ batchim
            return (True, False)
        else:
            # 10000+: ends in "만" which has ㄴ batchim
            return (True, False)
    else:
        # Ends in non-zero digit
        has_batch, has_rieul = digit_batchim[last_digit]
        return (has_batch, has_rieul)
